const won=n=>Math.round(n).toLocaleString('ko-KR')+'원',signed=n=>(n>0?'+':n<0?'−':'')+won(Math.abs(n));
let hidden=false,amounts=[];
function renderDashboard(){let sample;try{sample=DemoStore.read();document.querySelector('#save-status').textContent=AppAccount.isCloud()?'계정에 저장된 모의투자 기록입니다. 다른 기기에서도 같은 이메일로 이어서 이용하세요.':'이 브라우저에 저장된 연습 기록입니다. 실제 계정과 연결되지 않습니다.';}catch(e){document.querySelector('#save-status').textContent=e.message;return;}const holdings=sample.holdings.filter(s=>s.quantity>0),stockTotal=holdings.reduce((sum,s)=>sum+s.quantity*s.price,0),total=stockTotal+sample.cash,profit=total-sample.startingCash;document.querySelector('#total').textContent=won(total);document.querySelector('#stock-total').textContent=won(stockTotal);document.querySelector('#cash').textContent=won(sample.cash);document.querySelector('#profit').textContent=`${signed(profit)} (${profit>=0?'+':''}${(profit/sample.startingCash*100).toFixed(2)}%)`;document.querySelector('#profit').classList.toggle('loss',profit<0);document.querySelector('#holdings-title span').textContent=String(holdings.length);document.querySelector('#holdings').innerHTML=holdings.map(stock=>{const value=stock.quantity*stock.price,cost=stock.quantity*stock.average,change=value-cost;return `<article class="holding"><div><h3>${stock.name}</h3><p>${stock.quantity}주 보유</p></div><div class="holding-value"><strong class="private">${won(value)}</strong><p class="gain private ${change<0?'loss':''}">${signed(change)} (${change>=0?'+':''}${(change/cost*100).toFixed(2)}%)</p></div><details><summary>매수 가격과 예시 가격 보기</summary><p class="private">평균 매수 가격 ${won(stock.average)} · 예시 주가 ${won(stock.price)}</p><p>아직 팔지 않은 주식의 평가손익입니다.</p></details></article>`;}).join('')||'<p>보유 종목이 없습니다. 매수·매도 연습에서 종목을 살 수 있습니다.</p>';amounts=[...document.querySelectorAll('.private')].map(element=>({element,text:element.textContent}));AssetChart.render(sample,hidden);applyHidden();}
function applyHidden(){AssetChart.privacy(hidden);amounts.forEach(({element,text})=>{element.textContent=hidden?'금액 숨김':text;});document.querySelector('#visibility').textContent=hidden?'금액 보기':'금액 숨기기';document.querySelector('#visibility').setAttribute('aria-pressed',String(hidden));}
document.querySelector('#visibility').addEventListener('click',()=>{hidden=!hidden;applyHidden();});AppAccount.ready.then(()=>{DemoStore.subscribe(renderDashboard);renderDashboard();}).catch(e=>{document.querySelector('#save-status').textContent=e.message;});

